function fallbackActor(kind,color=0x79d9ee){const g=new THREE.Group(),metal=new THREE.MeshStandardMaterial({color,metalness:.72,roughness:.25,emissive:new THREE.Color(color).multiplyScalar(.11)}),dark=new THREE.MeshStandardMaterial({color:0x15232d,metalness:.8,roughness:.28});if(kind==='drone'){const core=new THREE.Mesh(new THREE.OctahedronGeometry(.55),metal);core.position.y=.7;g.add(core);for(const s of [-1,1]){const wing=new THREE.Mesh(new THREE.BoxGeometry(.95,.1,.3),dark);wing.position.set(s*.68,.72,0);g.add(wing)}}else if(kind==='alien'){const body=new THREE.Mesh(new THREE.IcosahedronGeometry(.62,1),metal);body.position.y=.9;body.scale.set(.9,1.3,.75);g.add(body);for(const s of [-1,1]){const leg=new THREE.Mesh(new THREE.CylinderGeometry(.12,.18,.8,6),dark);leg.position.set(s*.32,.35,0);g.add(leg)}}else{const torso=new THREE.Mesh(new THREE.BoxGeometry(.9,1.15,.58),metal);torso.position.y=1.3;g.add(torso);const head=new THREE.Mesh(new THREE.BoxGeometry(.58,.48,.52),dark);head.position.y=2.08;g.add(head);for(const s of [-1,1]){const leg=new THREE.Mesh(new THREE.BoxGeometry(.25,.9,.28),dark);leg.position.set(s*.25,.46,0);g.add(leg);const arm=new THREE.Mesh(new THREE.BoxGeometry(.22,.82,.24),metal);arm.position.set(s*.62,1.3,0);g.add(arm)}const gun=new THREE.Mesh(new THREE.BoxGeometry(.18,.18,1.25),dark);gun.position.set(.62,1.25,-.72);g.add(gun)}return g}
function normalizeModel(src,target=2){const root=new THREE.Group(),pivot=new THREE.Group(),m=SkeletonUtils.clone(src);pivot.add(m);root.add(pivot);m.updateMatrixWorld(true);m.traverse(o=>{if(o.isSkinnedMesh)o.skeleton.update()});const box=new THREE.Box3().setFromObject(m,true),sz=box.getSize(new THREE.Vector3()),scale=target/Math.max(sz.x,sz.y,sz.z,.01);pivot.scale.setScalar(scale);root.updateMatrixWorld(true);box.setFromObject(pivot,true);const center=box.getCenter(new THREE.Vector3());pivot.position.set(-center.x,-box.min.y,-center.z);root.updateMatrixWorld(true);m.traverse(o=>{if(o.isMesh){o.frustumCulled=false;o.geometry=o.geometry.clone();o.castShadow=!IS_TOUCH;o.receiveShadow=true;if(o.material)o.material=Array.isArray(o.material)?o.material.map(m=>m.clone()):o.material.clone()}});return root}
function loadModel(id){if(modelCache.has(id))return Promise.resolve(modelCache.get(id));return new Promise(resolve=>{let done=false;const timeout=setTimeout(()=>finish(null),30000);const finish=v=>{if(done)return;done=true;clearTimeout(timeout);modelCache.set(id,v);resolve(v)};const b64=window.VOIDSTORM_MODELS?.[id];if(!b64){finish(null);return}try{const bytes=Uint8Array.from(atob(b64),c=>c.charCodeAt(0));loader.parse(bytes.buffer,'',g=>{try{const b=new THREE.Box3().setFromObject(g.scene),sz=b.getSize(new THREE.Vector3());let meshes=0;g.scene.traverse(o=>{if(o.isMesh)meshes++});finish(meshes&&Number.isFinite(sz.length())&&sz.length()>.01?{scene:g.scene,animations:g.animations||[]}:null)}catch{finish(null)}},()=>finish(null))}catch{finish(null)}})}
let preloadPromise;
function preloadModels(){if(preloadPromise)return preloadPromise;preloadPromise=(async()=>{const ids=Object.keys(MODEL_URLS),status=$('#assetStatus');status.textContent='机库自检中…';await Promise.all(ids.map(loadModel));const ok=ids.filter(id=>modelCache.get(id)).length;status.className='assetStatus '+(ok===ids.length?'ok':'warn');status.textContent=ok===ids.length?'● 原创机体就绪 · 离线资源已就位':'● 部分资源异常 · 可视备用机体已就位'})();return preloadPromise}
function marker(radius,color,player=false){const m=new THREE.Mesh(new THREE.RingGeometry(radius*.9,radius,48),new THREE.MeshBasicMaterial({toneMapped:false,color,transparent:true,opacity:player?.82:.78,side:THREE.DoubleSide,depthWrite:false}));m.rotation.x=-Math.PI/2;m.position.y=.045;return m}
function visibilityBeacon(size,color){const g=new THREE.Group(),mat=new THREE.MeshBasicMaterial({toneMapped:false,color,transparent:true,opacity:.9,depthTest:false,depthWrite:false}),core=new THREE.Mesh(new THREE.OctahedronGeometry(.11),mat);core.position.y=Math.max(1.2,size*.64);const stem=new THREE.Mesh(new THREE.CylinderGeometry(.018,.018,.46,5),mat.clone());stem.position.y=core.position.y-.28;g.add(core,stem);g.renderOrder=9;return g}
function actorVisual(modelId,color,size=2,markRadius=.7,player=false){const data=modelCache.get(modelId);let authored=null;try{authored=originalActor(modelId==='drone'&&player?'escort':modelId)}catch(err){console.warn('Original model fallback',modelId)}const root=authored?normalizeModel(authored,size):data?normalizeModel(data.scene,size):normalizeModel(fallbackActor(modelId,color),size),tint=new THREE.Color(color);root.traverse(o=>{if(!o.isMesh||!o.material)return;o.castShadow=player&&!IS_TOUCH;o.frustumCulled=modelId==='crate'||modelId==='container';const mats=Array.isArray(o.material)?o.material:[o.material];for(const mat of mats){if(mat.color){mat.color.lerp(tint,mat.userData.original?0:player?.48:.3);mat.userData.vsBaseColor=mat.color.clone()}if(mat.emissive){mat.emissive.lerp(tint,mat.userData.original?0:player?.06:.10);mat.userData.vsBaseEmissive=mat.emissive.clone();mat.userData.vsBaseEmissiveIntensity=mat.emissiveIntensity||0;mat.emissiveIntensity=Math.max(mat.emissiveIntensity||0,player?.12:.26)}}});root.add(marker(markRadius,color,player));if(!player)root.add(visibilityBeacon(size,color));return{root,animations:authored?[]:data?.animations||[],fromAsset:!!authored||!!data,original:!!authored}}
function makeMixer(root,clips){const rig=originalRig(root);if(rig)return rig;if(!clips?.length)return null;const mixer=new THREE.AnimationMixer(root),find=(r)=>clips.find(c=>r.test(c.name));const defs={idle:find(/idle/i)||clips[0],run:find(/run|walk/i),attack:find(/shoot|attack|fire/i),hit:find(/hit|react|damage/i)};const actions={};for(const [k,c] of Object.entries(defs))if(c){actions[k]=mixer.clipAction(c);actions[k].enabled=true}if(actions.idle)actions.idle.play();return{mixer,actions,current:actions.idle?'idle':null,attackUntil:0,hitUntil:0}}
function playAnim(anim,name,fade=.12){if(!anim?.actions?.[name]||anim.current===name)return;const prev=anim.actions[anim.current],next=anim.actions[name];prev?.fadeOut(fade);next.reset().fadeIn(fade).play();anim.current=name}
function updateAnim(anim,dt,moving=false){if(!anim)return;if(anim.procedural){animateOriginal(anim,dt,moving,state.time);return}anim.mixer.update(dt);if(state.time<anim.hitUntil)playAnim(anim,'hit');else if(state.time<anim.attackUntil)playAnim(anim,'attack');else if(moving&&anim.actions.run)playAnim(anim,'run');else playAnim(anim,'idle')}
