function removeObject(obj){if(!obj)return;scene.remove(obj);obj.traverse(o=>{o.geometry?.dispose();if(o.isInstancedMesh)o.dispose();if(o.isSkinnedMesh)o.skeleton?.dispose();if(o.material)for(const m of (Array.isArray(o.material)?o.material:[o.material]))m.dispose()})}
