function weaponTick(dt){if(!state.hero)return;for(const [id,w] of Object.entries(state.weapons)){w.timer=(w.timer||0)-dt;if(w.timer>0)continue;fireWeapon(id,w)}}
function fireWeapon(id,w){const h=state.hero,p=h.mesh.position,lv=w.lv,evo=w.evo,pow=h.power,area=h.area,haste=h.haste,extra=h.projectiles-1,dur=h.duration;let t,dir,muzzle;
 if(id==='pulse'){t=nearestEnemy(p,22);if(t||state.manualAim){dir=state.manualAim?state.aim.clone():t.mesh.position.clone().sub(p).setY(0).normalize();muzzle=weaponMuzzle(h,dir);if(!state.manualAim)dir=t.mesh.position.clone().sub(muzzle).setY(0).normalize();const n=1+(lv>=3?1:0)+(evo?1:0)+Math.floor(extra*.5);fireFan(muzzle,dir,n,.26,(d)=>projectile(muzzle,d,evo?25:22,9.8*pow*(1+.22*(lv-1)),{color:evo?0xd994ff:0x6ff2ff,pierce:evo?4:Math.floor((lv-1)/3),homing:evo?.36:.08,evo}));audioCue('shot');fxBurst(muzzle,evo?0xd78cff:0x73efff,5,.75);if(h.anim)h.anim.attackUntil=state.time+.16}w.timer=(evo?.12:.30)*haste/(1+.075*(lv-1));return}
 if(id==='blade'){t=nearestEnemy(p,24);if(t){dir=state.manualAim?state.aim.clone():t.mesh.position.clone().sub(p).setY(0).normalize();muzzle=p.clone().add(new THREE.Vector3(0,1.0,0));const n=Math.min(5,1+Math.floor((lv-1)/2)+extra+(evo?1:0));fireFan(muzzle,dir,n,.52,(d)=>projectile(muzzle,d,17,16*pow*(1+.18*(lv-1)),{blade:true,color:0x73ffe0,pierce:evo?8:4,returnAt:evo?.42:.62,life:evo?2.0:1.65,rad:.34,evo}))}w.timer=(evo?1.05:1.55)*haste;return}
 if(id==='mine'){const n=Math.min(8,2+Math.floor(lv/2)+extra+(evo?2:0));for(let i=0;i<n;i++){const a=i/n*Math.PI*2+state.time*.7,rr=1.8+Math.random()*2.1,pos=p.clone().add(new THREE.Vector3(Math.cos(a)*rr,0.05,Math.sin(a)*rr));createMine(pos,22*pow*(1+.2*(lv-1)),2.1*area,evo)}w.timer=(evo?2.4:3.3)*haste;return}
 if(id==='chain'){chainLightning(p.clone().add(new THREE.Vector3(0,1.1,0)),14*pow*(1+.2*(lv-1)),3+lv+extra+(evo?3:0),evo?0xd790ff:0x72e9ff);w.timer=(evo?1.15:1.85)*haste;return}
 if(id==='orbital'){const targets=state.enemies.filter(e=>!e.dead).sort(()=>Math.random()-.5).slice(0,Math.min(7,1+Math.floor(lv/2)+extra+(evo?2:0)));for(const e of targets)orbitalStrike(e.mesh.position.clone(),28*pow*(1+.2*(lv-1)),(1.55+.16*lv)*area*(evo?1.2:1),evo?0xe398ff:0x78dfff);w.timer=(evo?3.2:4.6)*haste;return}
 if(id==='slicer'){const r=(2.5+.23*lv)*area*(evo?1.2:1),n=3+Math.floor(lv/2)+extra+(evo?2:0);fxSlicerBurst(r,n,evo?0xe9a0ff:0x9cf9ff);for(const e of enemyInRadius(p,r+.7))damageEnemy(e,10*pow*(1+.22*(lv-1)));w.timer=(evo?.58:.88)*haste;return}
 if(id==='ember'){t=nearestEnemy(p,26);if(t){dir=state.manualAim?state.aim.clone():t.mesh.position.clone().sub(p).setY(0).normalize();muzzle=p.clone().add(new THREE.Vector3(0,1.3,0));const r=(1.55+.18*lv)*area*(evo?1.25:1);projectile(muzzle,dir,18,13*pow*(1+.18*(lv-1)),{color:evo?0xff7af1:0xff9a5d,pierce:evo?2:0,onHit:(e,pos)=>createZone(pos.clone().setY(.05),r,8.5*pow*(1+.16*(lv-1)),(2.8+.35*lv)*dur*(evo?1.25:1),evo?0xff66dc:0xff7a48),evo})}w.timer=(evo?.72:1.12)*haste;return}
 if(id==='sentinel'){t=nearestEnemy(p,28);if(t){dir=t.mesh.position.clone().sub(p).setY(0).normalize();const right=new THREE.Vector3(dir.z,0,-dir.x),n=Math.min(5,1+Math.floor(lv/2)+extra+(evo?2:0));for(let i=0;i<n;i++){const side=(i-(n-1)/2)*.72,m=companions[i]?.position.clone()||p.clone().add(new THREE.Vector3(0,1.7,0)).addScaledVector(right,side);fxBurst(m,0x86a7ff,4,.6);projectile(m,dir.clone(),20,8.6*pow*(1+.17*(lv-1)),{color:evo?0xd28cff:0x86a7ff,homing:evo?.65:.35,pierce:evo?2:0,evo})}}w.timer=(evo?.38:.64)*haste;return}
 if(id==='echo'){t=nearestEnemy(p,28);if(t){dir=state.manualAim?state.aim.clone():t.mesh.position.clone().sub(p).setY(0).normalize();muzzle=p.clone().add(new THREE.Vector3(0,1.15,0));const n=Math.min(9,2+Math.floor(lv/2)+extra+(evo?3:0));fireFan(muzzle,dir,n,1.05,(d)=>projectile(muzzle,d,18,11.5*pow*(1+.17*(lv-1)),{blade:true,color:evo?0xf196ff:0x86f5d6,pierce:6,bounce:evo?5:2,life:3.4,rad:.3,evo}))}w.timer=(evo?1.15:1.7)*haste;return}
 if(id==='field'){const r=(2.45+.2*lv)*area*(evo?1.3:1);for(const e of enemyInRadius(p,r))damageEnemy(e,6.4*pow*(1+.2*(lv-1)));fxRing(p,r,evo?0xcc78ff:0x73e7ff);w.timer=(evo?.34:.52)*haste;return}
 if(id==='vortex'){const n=Math.min(12,4+lv+extra+(evo?2:0)),phase=(w.phase||0)+.58;w.phase=phase;for(let i=0;i<n;i++){const a=phase+i/n*Math.PI*2,dd=new THREE.Vector3(Math.cos(a),0,Math.sin(a));projectile(p.clone().add(new THREE.Vector3(0,1.0,0)),dd,13,7.5*pow*(1+.18*(lv-1)),{color:evo?0xf17cff:0x72dfff,pierce:evo?3:1,life:2.4,rad:.26,evo})}w.timer=(evo?.62:.92)*haste;return}
 if(id==='annihilator'){const r=(11+lv*.8)*area*(evo?1.2:1),dmg=38*pow*(1+.22*(lv-1));fxRing(p,r,evo?0xff9dea:0xf7e78a);fxBurst(p.clone().add(new THREE.Vector3(0,1.2,0)),evo?0xff9dea:0xf7e78a,40,2);for(const e of enemyInRadius(p,r))damageEnemy(e,dmg*((e.elite||e.boss)?.55:1));w.timer=(evo?7.4:11.2)*haste;return}}
function createMine(pos,dmg,r,evo){const m=new THREE.Mesh(new THREE.CylinderGeometry(.3,.4,.14,12),new THREE.MeshBasicMaterial({toneMapped:false,color:evo?0xd487ff:0x67dcff}));m.position.copy(pos);fxRing(pos,.8,evo?0xd487ff:0x67dcff);scene.add(m);state.fx.push({mesh:m,life:evo?2.1:2.7,max:evo?2.1:2.7,update:f=>{f.mesh.scale.setScalar(1+.18*Math.sin(state.time*8)),f.mesh.rotation.y+=.04},end:()=>{for(const e of enemyInRadius(pos,r*(evo?1.5:1)))damageEnemy(e,dmg*(evo?1.55:1));fxBurst(pos.clone().add(new THREE.Vector3(0,.3,0)),evo?0xe38bff:0x66dfff,22,1.4);fxRing(pos,r*(evo?1.5:1),evo?0xe38bff:0x66dfff)}})}
function createZone(pos,r,dps,dur,color,event=false){const m=new THREE.Mesh(new THREE.CircleGeometry(r,36),new THREE.MeshBasicMaterial({toneMapped:false,color,transparent:true,opacity:event?.18:.12,side:THREE.DoubleSide,depthWrite:false}));m.rotation.x=-Math.PI/2;m.position.copy(pos);m.position.y=.05;scene.add(m);state.zones.push({mesh:m,r,dps,life:dur,tick:0,event,capture:0,done:false})}
function fxRing(pos,r,color){const m=new THREE.Mesh(new THREE.RingGeometry(.88,1,40),new THREE.MeshBasicMaterial({toneMapped:false,color,transparent:true,opacity:.75,side:THREE.DoubleSide,depthWrite:false}));m.rotation.x=-Math.PI/2;m.position.copy(pos);m.position.y=.12;scene.add(m);state.fx.push({mesh:m,life:.38,max:.38,update:f=>{const t=1-f.life/f.max;f.mesh.scale.setScalar(r*t);f.mesh.material.opacity=1-t}})}
function fxLine(a,b,color=0x68e9ff,width=.07){const d=b.clone().sub(a),len=d.length(),m=new THREE.Mesh(new THREE.CylinderGeometry(width,width,len,5),new THREE.MeshBasicMaterial({toneMapped:false,color,transparent:true,opacity:.8}));m.position.copy(a).add(b).multiplyScalar(.5);m.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),d.normalize());scene.add(m);state.fx.push({mesh:m,life:.11,max:.11,update:f=>f.mesh.material.opacity=f.life/f.max})}
function damageNumber(world,n,crit){const layer=$('#damageLayer');if(layer.childElementCount>45)return;const p=world.clone().project(camera);if(p.z>1)return;const el=document.createElement('div');el.className='dmg';el.textContent=(crit?'✦ ':'')+n;el.style.color=crit?'#ffd578':'#d9f8ff';el.style.left=((p.x*.5+.5)*innerWidth)+'px';el.style.top=((-p.y*.5+.5)*innerHeight)+'px';layer.appendChild(el);setTimeout(()=>el.remove(),750)}

function spawnGem(pos,xp){const g=new THREE.Group(),core=new THREE.Mesh(new THREE.OctahedronGeometry(.18),new THREE.MeshBasicMaterial({toneMapped:false,color:0x8af0ff})),glow=new THREE.Mesh(new THREE.OctahedronGeometry(.31),new THREE.MeshBasicMaterial({toneMapped:false,color:0x5fd9ff,transparent:true,opacity:.18,depthWrite:false})),tail=new THREE.Mesh(new THREE.CylinderGeometry(.025,.065,1.15,6),new THREE.MeshBasicMaterial({toneMapped:false,color:0x63dcff,transparent:true,opacity:.48,depthWrite:false}));tail.visible=false;g.add(glow,core,tail);g.position.copy(pos);g.position.y=.28;scene.add(g);state.gems.push({mesh:g,core,glow,tail,xp,life:45,pull:false,pullAge:0,phase:Math.random()*Math.PI*2,vel:new THREE.Vector3()})}
function spawnPickup(pos,type){const col={heart:0x7bff9b,coin:0xffd06a,magnet:0x7f9cff,chest:0xd88cff}[type],m=new THREE.Mesh(new THREE.IcosahedronGeometry(type==='chest'?.34:.2,0),new THREE.MeshBasicMaterial({toneMapped:false,color:col}));m.position.copy(pos);m.position.y=.28;scene.add(m);state.pickups.push({mesh:m,type,life:36})}
function applyPickup(p){const h=state.hero;if(p.type==='heart')h.hp=Math.min(h.maxHp,h.hp+h.maxHp*.3);if(p.type==='coin')state.coins+=22;if(p.type==='magnet')for(const g of state.gems)g.pull=true;if(p.type==='chest'){state.coins+=50;h.hp=Math.min(h.maxHp,h.hp+h.maxHp*.2);showToast('补给箱：+50 CR · 修复装甲')}}
function flashHealScreen(){const f=$('#healFlash');f.classList.remove('show');void f.offsetWidth;f.classList.add('show');setTimeout(()=>f.classList.remove('show'),900)}
function addXp(v){state.xp+=v*(state.hero?.xpGain||1);if(state.paused||!state.running)return;while(state.xp>=state.xpNeed&&state.running){state.xp-=state.xpNeed;state.level++;state.xpNeed=Math.floor(state.xpNeed*1.18+5);if(state.hero){state.hero.hp=state.hero.maxHp;state.hero.shield=Math.max(state.hero.shield,state.hero.maxHp*.08)}if(state.level===3)state.pendingUnlock='E 棱镜壁垒已解锁';if(state.level===6)state.pendingUnlock='R 离子超载已解锁';audioCue('level');flashHealScreen();showToast('等级提升 · 装甲完全修复');openLevelUp();break}checkAchievements()}
function buildChoices(){const pool=[],unique=(o)=>{if(!pool.some(x=>x.kind===o.kind&&x.id===o.id))pool.push(o)},weaponCount=Object.keys(state.weapons).length,passiveCount=Object.keys(state.passives).length;
 for(const [id,w] of Object.entries(state.weapons)){const def=WEAPONS[id];if(w.lv>=def.max&&!w.evo&&(state.passives[def.pair]||0)>=3)unique({kind:'evo',id,name:def.evo,desc:`完成 ${def.name} 的形态进化，攻击机制显著强化。`,pair:def.pair});else if(w.lv<def.max)unique({kind:'weapon',id,name:def.name,desc:def.desc,pair:def.pair})}
 if(weaponCount<5)for(const [id,def] of Object.entries(WEAPONS))if(!state.weapons[id])unique({kind:'weapon',id,name:def.name,desc:def.desc,pair:def.pair,newCard:true});
 for(const [id,p] of Object.entries(PASSIVES)){const lv=state.passives[id]||0;if(lv>0&&lv<p.max)unique({kind:'passive',id,name:p.name,desc:p.desc});else if(lv===0&&passiveCount<6)unique({kind:'passive',id,name:p.name,desc:p.desc,newCard:true})}
 const c=[];while(c.length<3&&pool.length){let ticket=Math.random()*pool.reduce((n,x)=>n+choiceWeight(x),0),at=pool.length-1;for(let i=0;i<pool.length;i++){ticket-=choiceWeight(pool[i]);if(ticket<0){at=i;break}}c.push(pool.splice(at,1)[0])}const utils=[{kind:'utility',id:'repair',name:'紧急纳米修复',desc:'立即获得 30% 护盾，并回满生命。'},{kind:'utility',id:'credits',name:'战场回收',desc:'立即获得 75 CR。'},{kind:'utility',id:'overclock',name:'临时过载',desc:'本局永久伤害 +6%。'}];while(c.length<3){const u=utils[c.length%utils.length];if(!c.some(x=>x.id===u.id))c.push(u);else c.push(utils[(c.length+1)%utils.length])}return c.slice(0,3)}
function cardNextText(c,lv){if(c.kind==='utility')return '即时战术收益';const ids=c.kind==='passive'?Object.keys(WEAPONS).filter(id=>WEAPONS[id].pair===c.id):[c.id];const head=c.kind==='weapon'?(c.newCard?'新增战斗机制':weaponUpgradeText(c.id,lv)):c.kind==='passive'?(c.newCard?'占用 1 个属性槽':'强化已安装属性'):'进化后改变攻击形态';return head+(choiceWeight(c)>1?'<span class="synergy">契合构筑 · 抽取权重小幅提升</span>':'')+(ids.length?ids.map(id=>evolutionRow(id,true)).join(''):'<span class="evoNote">通用强化 · 无专属进化配方</span>')}
function choiceWeight(c){if(c.kind==='evo')return 1.4;if(c.kind==='weapon')return state.passives[WEAPONS[c.id].pair]?1.25:1;if(c.kind==='passive')return Object.entries(state.weapons).some(([id,w])=>!w.evo&&WEAPONS[id].pair===c.id)?1.25:1;return 1}
function evolutionRow(id,compact=false){const d=WEAPONS[id],w=state.weapons[id],pl=state.passives[d.pair]||0,ready=w?.lv>=5&&pl>=3,blocked=(!w&&Object.keys(state.weapons).length>=5)||(!pl&&Object.keys(state.passives).length>=6);return `<div class="evoRecipe ${w?.evo?'complete':ready?'ready':''}">${compact?'':icon(id)}<div><b>${d.evo}</b><span>${d.name} ${w?.lv||0}/5 + ${PASSIVES[d.pair].name} ${pl}/3</span><div class="evoSteps">${Array.from({length:5},(_,i)=>`<i class="${i<(w?.lv||0)?'lit':''}"></i>`).join('')}<em>+</em>${Array.from({length:3},(_,i)=>`<i class="attr ${i<pl?'lit':''}"></i>`).join('')}</div><small>${w?.evo?'已完成进化':blocked?'槽位已满 · 本局无法补齐':ready?'条件齐全 · 升级时有机会出现进化卡':`还需：${!w||w.lv<5?'技能 Lv.5 ':''}${pl<3?PASSIVES[d.pair].name+' Lv.3':''}`}</small></div></div>`}
function openGuide(){state.guideFocus=document.activeElement;clearInput();state.guideWasPaused=state.paused;state.paused=true;$('#evolutionList').innerHTML=Object.keys(WEAPONS).map(id=>evolutionRow(id)).join('');$('#evolutionModal').classList.remove('hidden');$('#guideClose').focus()}
function closeGuide(){$('#evolutionModal').classList.add('hidden');state.paused=state.guideWasPaused;state.guideFocus?.focus();}


function openLevelUp(){state.paused=true;const box=$('#choices');box.innerHTML='';for(const c of buildChoices()){const b=document.createElement('button');b.className='choice '+c.kind;let lv=c.kind==='weapon'?state.weapons[c.id]?.lv||0:c.kind==='passive'?state.passives[c.id]||0:0,type=c.kind==='weapon'?'技能卡':c.kind==='passive'?'属性卡':c.kind==='evo'?'进化卡':'战术卡';b.innerHTML=`<span class="cardIndex">0${box.children.length+1}</span><div class="cardType">${type}${c.newCard?' · NEW':''}</div><div class="ico">${icon(c.id)}</div><div class="level">${c.kind==='evo'?'EVOLUTION':c.kind==='utility'?'UTILITY':`LV ${lv} → ${lv+1}`}</div><h3>${c.name}</h3><p>${c.desc}</p><div class="next">${cardNextText(c,lv)}</div>`;b.onclick=()=>selectChoice(c);box.appendChild(b)}$('#buildSummary').innerHTML=buildInventory();$('#levelModal').classList.remove('hidden')}
function selectChoice(c){if(!state.running||!state.paused||!$('#evolutionModal').classList.contains('hidden')||$('#levelModal').classList.contains('hidden'))return;audioCue('select');clearInput();if(c.kind==='weapon'){if(!state.weapons[c.id])state.weapons[c.id]={lv:1,timer:.08,evo:false};else state.weapons[c.id].lv++}else if(c.kind==='passive'){state.passives[c.id]=(state.passives[c.id]||0)+1;refreshDerived()}else if(c.kind==='evo'){state.weapons[c.id].evo=true;state.evolutions++;state.questEvo=true;showToast('技能进化 · '+WEAPONS[c.id].evo)}else if(c.id==='repair'){state.hero.shield+=state.hero.maxHp*.3}else if(c.id==='credits')state.coins+=75;else if(c.id==='overclock'){state.bonusPower*=1.06;refreshDerived()}refreshDerived();state.hero.hp=state.hero.maxHp;fxRing(state.hero.mesh.position,2.8,0x78ffad);fxBurst(state.hero.mesh.position.clone().add(new THREE.Vector3(0,1,0)),0x79ffae,16,1);$('#levelModal').classList.add('hidden');state.paused=false;if(state.pendingUnlock){showToast(state.pendingUnlock);state.pendingUnlock=null}updateHUD(true);checkAchievements();if(state.xp>=state.xpNeed)addXp(0)}

function useSkill(){if(!state.running||state.paused||!state.hero)return;const h=state.hero;if(state.level<3){showToast('棱镜壁垒 · LV3 解锁');return}if(h.skillCd>0)return;h.skillCd=12*h.haste;h.shield=Math.min(h.maxHp,h.shield+h.maxHp*.35);h.barrier={left:3,pulse:0,absorbed:0};const g=new THREE.Group();for(let i=0;i<6;i++){const a=i*Math.PI/3,m=new THREE.Mesh(new THREE.PlaneGeometry(1.25,1.8),new THREE.MeshBasicMaterial({color:0x6cf6e1,toneMapped:false,transparent:true,opacity:.16,side:THREE.DoubleSide,depthWrite:false}));m.position.set(Math.sin(a)*2.2,1.3,Math.cos(a)*2.2);m.rotation.y=a;g.add(m);const outline=new THREE.LineSegments(new THREE.EdgesGeometry(m.geometry),new THREE.LineBasicMaterial({color:0x8effeb,transparent:true,opacity:.8}));m.add(outline)}g.position.copy(h.mesh.position);scene.add(g);state.fx.push({mesh:g,life:3,max:3,update:(f,dt)=>{f.mesh.position.copy(h.mesh.position);f.mesh.rotation.y+=dt*.65}});fxRing(h.mesh.position,2.8,0x83ffe6);audioCue('dash');showToast('E · 棱镜壁垒 / 3 秒后反击');updateCooldowns()}
function triggerCore(){const h=state.hero;if(!h)return;h.coreKills=(h.coreKills||0)+1;if(h.coreKills>=12){h.coreKills=0;h.coreTime=4;h.shield=Math.min(h.maxHp,h.shield+h.maxHp*.10);fxRing(h.mesh.position,2.1,0xffd178);fxBurst(h.mesh.position.clone().add(new THREE.Vector3(0,1.5,0)),0xffd178,12,.8);showToast('被动 · 自适应核心 / 火力 +15% · 护盾 +10%')}}
function updateDefense(dt){const h=state.hero;h.coreTime=Math.max(0,(h.coreTime||0)-dt);const b=h.barrier;if(!b)return;b.left-=dt;b.pulse-=dt;if(b.pulse<=0){b.pulse=1;fxRing(h.mesh.position,3.4,0x7bffde);for(const e of enemyInRadius(h.mesh.position,3.4))damageEnemy(e,14*h.power)}if(b.left<=0){h.barrier=null;const r=5.5*h.area;for(const e of enemyInRadius(h.mesh.position,r))damageEnemy(e,(55+b.absorbed*.65)*h.power);fxRing(h.mesh.position,r,0xb4fff0);fxSlicerBurst(r,12,0x8dffe8);fxBurst(h.mesh.position.clone().setY(1.2),0xc1ffee,24,1.5);showToast('棱镜反击 · '+Math.round(55+b.absorbed*.65)+' 基础伤害')}}


function createUltArray(){const h=state.hero,g=new THREE.Group();g.position.copy(h.mesh.position);for(const rr of [1.8,3.2,4.5]){const ring=new THREE.Mesh(new THREE.RingGeometry(rr*.94,rr,48),new THREE.MeshBasicMaterial({toneMapped:false,color:0xd88cff,transparent:true,opacity:.55,side:THREE.DoubleSide,depthWrite:false}));ring.rotation.x=-Math.PI/2;g.add(ring)}for(let i=0;i<8;i++){const a=i/8*Math.PI*2,b=new THREE.Mesh(new THREE.BoxGeometry(.08,.06,1.5),new THREE.MeshBasicMaterial({toneMapped:false,color:0xf0a8ff,transparent:true,opacity:.62,depthWrite:false}));b.position.set(Math.cos(a)*4,.16,Math.sin(a)*4);b.rotation.y=-a;g.add(b)}for(let i=0;i<6;i++){const a=i/6*Math.PI*2,lance=boltVisual(0xcc9bff,1.8,.08);lance.position.set(Math.cos(a)*3.2,3.2,Math.sin(a)*3.2);g.add(lance)}scene.add(g);state.fx.push({mesh:g,life:3.6,max:3.6,update:(f,dt)=>{f.mesh.position.copy(h.mesh.position);f.mesh.rotation.y+=dt*1.8;const k=.75+.25*Math.sin(state.time*8);f.mesh.scale.setScalar(k)}})}
function useUlt(){if(!state.running||state.paused||!state.hero)return;if(state.level<6){showToast('离子超载 · LV6 解锁');return}if(state.charge<100){showToast(`离子超载充能 ${Math.floor(state.charge)}% / 100%`);return}if(state.ultSequence)return;const h=state.hero;state.charge=0;h.shield+=h.maxHp*.45;h.invuln=.7;state.ultSequence={left:42,timer:0,duration:3.5,elapsed:0,strike:0};audioCue('ult');createUltArray();fxBurst(h.mesh.position.clone().add(new THREE.Vector3(0,1.4,0)),0xd98cff,30,1.6);showToast('R · 离子超载 / 天罚阵列');updateCooldowns()}
function updateSkillSequence(dt){const u=state.ultSequence;if(!u)return;u.elapsed+=dt;u.timer-=dt;u.strike-=dt;if(u.strike<=0){u.strike=.65;const target=nearestEnemy(state.hero.mesh.position,30);if(target)orbitalStrike(target.mesh.position.clone(),38*state.hero.power,2.6*state.hero.area,0xe4a6ff)}if(u.left>0&&u.timer<=0){u.timer=.07;u.left--;const h=state.hero,t=nearestEnemy(h.mesh.position,38);if(t){const d=t.mesh.position.clone().sub(h.mesh.position).setY(0).normalize(),m=h.mesh.position.clone().add(new THREE.Vector3(0,1.6,0)).addScaledVector(d,.85);projectile(m,d,28,19*h.power,{color:0xe49bff,pierce:4,homing:.42,evo:true,life:2.2})}}if(u.elapsed>=u.duration){const h=state.hero,r=9*h.area;for(const e of enemyInRadius(h.mesh.position,r))damageEnemy(e,90*h.power);fxRing(h.mesh.position,r,0xf1a2ff);fxSlicerBurst(r,16,0xf1c6ff);fxLine(h.mesh.position.clone().setY(12),h.mesh.position.clone().setY(.2),0xf3dfff,.5);fxBurst(h.mesh.position.clone().add(new THREE.Vector3(0,1.2,0)),0xf0a2ff,42,1.8);state.ultSequence=null;showToast('离子超载 · 终端冲击')}}
function updateSkillHUD(){const h=state.hero;if(!h)return;$('#coreStatus').innerHTML=icon('core')+`<span>自适应核心 <b>${h.coreTime>0?'超频 '+h.coreTime.toFixed(1)+'s':(h.coreKills||0)+'/12 击杀'}</b></span>`;const eLocked=state.level<3,rLocked=state.level<6,ec=$('#skillECard'),rc=$('#skillRCard');ec.classList.toggle('locked',eLocked);rc.classList.toggle('locked',rLocked);$('#skillEState').textContent=eLocked?'LV3 解锁':h.barrier?`防御 ${h.barrier.left.toFixed(1)}s`:h.skillCd>0?`${h.skillCd.toFixed(1)}s`:'READY';$('#skillRState').textContent=rLocked?'LV6 解锁':state.ultSequence?'释放中':state.charge>=100?'READY':`充能 ${Math.floor(state.charge)}%`;$('#eBtnText').textContent=eLocked?'E · Lv3':h.skillCd>0?'E '+h.skillCd.toFixed(1)+'s':'E 就绪';$('#rBtnText').textContent=rLocked?'R · Lv6':state.ultSequence?'R 释放中':'R '+Math.floor(state.charge)+'%';$('#eBtn').disabled=eLocked;$('#rBtn').disabled=rLocked}
