function updateHero(dt){const h=state.hero;if(!h)return;let x=(key.KeyD||key.ArrowRight?1:0)-(key.KeyA||key.ArrowLeft?1:0)+moveTouch.x,z=(key.KeyS||key.ArrowDown?1:0)-(key.KeyW||key.ArrowUp?1:0)+moveTouch.y,dir=new THREE.Vector3(x,0,z);if(dir.lengthSq()>1)dir.normalize();h.moving=dir.lengthSq()>.015;moveWithCollision(h.mesh,dir.multiplyScalar(h.speed*dt),.6);if(h.regen>0)h.hp=Math.min(h.maxHp,h.hp+h.maxHp*h.regen*dt);h.invuln=Math.max(0,h.invuln-dt);h.skillCd=Math.max(0,h.skillCd-dt);h.ultCd=Math.max(0,h.ultCd-dt);if(state.manualAim){if(IS_TOUCH){if(aimTouch.lengthSq()>.04)state.aim.set(aimTouch.x,0,aimTouch.y).normalize()}else{const ndc=new THREE.Vector2(mouse.x/innerWidth*2-1,-mouse.y/innerHeight*2+1),ray=new THREE.Raycaster();ray.setFromCamera(ndc,camera);const hit=new THREE.Vector3();const hasHit=ray.ray.intersectPlane(new THREE.Plane(new THREE.Vector3(0,1,0),0),hit);if(hasHit)state.aim.copy(hit.sub(h.mesh.position).setY(0).normalize())}}else{const t=nearestEnemy(h.mesh.position,60);if(t)state.aim.copy(t.mesh.position.clone().sub(h.mesh.position).setY(0).normalize())}if(state.aim.lengthSq()<.1)state.aim.set(0,0,-1);h.mesh.rotation.y=Math.atan2(state.aim.x,state.aim.z);syncCamera();updateAnim(h.anim,dt,h.moving);updateCooldowns()}
function updateEnemies(dt){const hp=state.hero.mesh.position;for(const e of state.enemies){if(e.dead)continue;e.flash=Math.max(0,e.flash-dt);if(e.flash<=0){e.mesh.scale.lerp(e.baseScale,.24);if(e.hitVisual)enemyFlashMaterials(e,false);}e.touch-=dt;e.shoot-=dt;e.charge-=dt;e.windup=Math.max(0,(e.windup||0)-dt);if(e.slow>0)e.slow-=dt;for(const other of state.enemies){if(other===e||other.dead||e.boss)continue;const dx=e.mesh.position.x-other.mesh.position.x,dz=e.mesh.position.z-other.mesh.position.z,dd=dx*dx+dz*dz,min=(e.rad+other.rad)*.8;if(dd>0.0001&&dd<min*min){const k=(min-Math.sqrt(dd))*dt*2/Math.sqrt(dd);e.mesh.position.x+=dx*k;e.mesh.position.z+=dz*k}}const d=Math.sqrt(distSqXZ(hp,e.mesh.position)),dir=hp.clone().sub(e.mesh.position).setY(0).normalize(),speed=e.speed*(e.slow>0?.38:1);steerAroundProps(e.mesh.position,dir,e.rad,e.mesh.id);if(e.ranged&&!e.boss&&d<13){if(d<7)moveWithCollision(e.mesh,dir.clone().multiplyScalar(-speed*.42*dt),e.rad);else if(d>10)moveWithCollision(e.mesh,dir.clone().multiplyScalar(speed*.55*dt),e.rad);if(e.shoot<=0){enemyShot(e,hp.clone().add(new THREE.Vector3(0,1,0)));e.shoot=rand(1.55,2.4)}}else if(!e.boss||!e.windup)moveWithCollision(e.mesh,dir.multiplyScalar(speed*dt),e.rad);if(e.boss&&e.shoot<=0)bossPattern(e);if(d<e.rad+.62&&e.touch<=0){hitHero(e.dmg);e.touch=.72}e.mesh.rotation.y=Math.atan2(dir.x,dir.z);if(e.type==='drone')e.mesh.position.y=.55+Math.sin(state.time*5+e.mesh.id)*.08;else e.mesh.position.y=0;updateAnim(e.anim,dt,true)}state.enemies=state.enemies.filter(e=>!e.dead)}
function updateProjectiles(dt){for(const p of state.projectiles){p.life-=dt;p.age+=dt;const prev=p.mesh.position.clone();if(p.returnAt&&!p.returning&&p.age>=p.returnAt){p.returning=true;p.hit.clear()}if(p.returning){const d=state.hero.mesh.position.clone().sub(p.mesh.position).setY(0);if(d.lengthSq()>.01)p.vel.lerp(d.normalize().multiplyScalar(Math.max(13,p.vel.length())),clamp(4.5*dt,0,1))}else if(p.homing>0){const t=nearestEnemy(p.mesh.position,12);if(t){const d=t.mesh.position.clone().sub(p.mesh.position).setY(0).normalize().multiplyScalar(p.vel.length());p.vel.lerp(d,clamp(p.homing*dt,0,1))}}orientBolt(p.mesh,p.vel);p.mesh.position.addScaledVector(p.vel,dt);if(p.bounce>0&&Math.hypot(p.mesh.position.x,p.mesh.position.z)>43){const n=new THREE.Vector3(p.mesh.position.x,0,p.mesh.position.z).normalize(),dot=p.vel.dot(n);p.vel.addScaledVector(n,-2*dot);const rr=Math.hypot(p.mesh.position.x,p.mesh.position.z);if(rr>42.7){p.mesh.position.x*=42.7/rr;p.mesh.position.z*=42.7/rr}p.bounce--;p.hit.clear();fxBurst(p.mesh.position.clone(),p.color,5,.55)}for(const e of state.enemies){if(e.dead||p.hit.has(e))continue;if(segmentDistanceSq(prev,p.mesh.position,e.mesh.position)<(p.rad+e.rad+.22)**2){p.hit.add(e);fxBurst(p.mesh.position.clone(),p.color,p.evo?15:9,p.evo?1.05:.8);damageEnemy(e,p.dmg);p.onHit?.(e,p.mesh.position.clone());if(p.explode>0){for(const x of enemyInRadius(e.mesh.position,p.explode))if(x!==e)damageEnemy(x,p.dmg*.65);fxRing(e.mesh.position,p.explode,p.color)}if(p.pierce>0)p.pierce--;else{p.life=0;break}}}if(p.returning&&distSqXZ(p.mesh.position,state.hero.mesh.position)<.5)p.life=0}
 for(const p of state.projectiles)if(p.life<=0)removeObject(p.mesh);state.projectiles=state.projectiles.filter(p=>p.life>0);for(const p of state.enemyProjectiles){const prev=p.mesh.position.clone();p.life-=dt;orientBolt(p.mesh,p.vel);p.mesh.position.addScaledVector(p.vel,dt);if(state.hero.barrier&&segmentDistanceSq(prev,p.mesh.position,state.hero.mesh.position)<(2.5+p.rad)**2){state.hero.barrier.absorbed=Math.min(state.hero.maxHp,state.hero.barrier.absorbed+p.dmg);fxRing(p.mesh.position,.6,0x8dffe8);p.life=0;continue}if(segmentDistanceSq(prev,p.mesh.position,state.hero.mesh.position)<(.68+p.rad)**2){fxBurst(p.mesh.position.clone(),p.color||0xff704f,10,1);hitHero(p.dmg);p.life=0}}for(const p of state.enemyProjectiles)if(p.life<=0)removeObject(p.mesh);state.enemyProjectiles=state.enemyProjectiles.filter(p=>p.life>0)}
function updateZones(dt){for(const z of state.zones){z.life-=dt;z.tick-=dt;z.mesh.material.opacity=(z.event?.14:.09)+(z.event?.08:.04)*Math.sin(state.time*5);if(!z.event&&z.tick<=0){for(const e of enemyInRadius(z.mesh.position,z.r))damageEnemy(e,z.dps*.35,false);z.tick=.35}}for(const z of state.zones)if(z.life<=0)removeObject(z.mesh);state.zones=state.zones.filter(z=>z.life>0)}
