function updateDrops(dt){const hp=state.hero.mesh.position,targetBase=hp.clone().add(new THREE.Vector3(0,.78,0));for(const g of state.gems){g.life-=dt;g.core.rotation.y+=dt*5;g.glow.rotation.y-=dt*2.5;let d=Math.sqrt(distSqXZ(g.mesh.position,hp));if(d<state.hero.magnet||g.pull){if(!g.pull){g.pull=true;fxRing(g.mesh.position,.5,0x8ce6e0)}g.pullAge+=dt;const target=targetBase.clone(),to=target.sub(g.mesh.position),dist=Math.max(.001,to.length()),dir=to.clone().normalize(),tangent=new THREE.Vector3(-dir.z,0,dir.x).multiplyScalar(Math.sin(g.pullAge*11+g.phase)*Math.min(2.0,dist*.24));const desired=dir.multiplyScalar(7+Math.min(27,g.pullAge*20)+12/(dist+.7)).add(tangent);g.vel.lerp(desired,clamp(dt*6.5,0,1));g.mesh.position.addScaledVector(g.vel,Math.min(dt,dist/Math.max(.01,g.vel.length())));const vdir=g.vel.clone().normalize();g.tail.visible=true;g.tail.scale.y=clamp(g.vel.length()/10,.55,2.3);g.tail.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),vdir.clone().multiplyScalar(-1));g.tail.position.copy(vdir).multiplyScalar(-.48);const sc=clamp(dist/2.5,.28,1);g.core.scale.setScalar(sc);g.glow.scale.setScalar(sc*(1.2+.2*Math.sin(state.time*14+g.phase)))}if(g.pull&&g.mesh.position.distanceTo(targetBase)<.55){audioCue('xp');addXp(g.xp);fxBurst(targetBase.clone(),0x82ecff,6,.55);g.life=0}}
 for(const g of state.gems)if(g.life<=0)removeObject(g.mesh);state.gems=state.gems.filter(g=>g.life>0);for(const p of state.pickups){p.life-=dt;p.mesh.rotation.y+=dt*2;if(p.mesh.position.distanceTo(hp)<.75){applyPickup(p);p.life=0}}for(const p of state.pickups)if(p.life<=0)removeObject(p.mesh);state.pickups=state.pickups.filter(p=>p.life>0)}
function updateEventZones(dt){for(const z of state.zones){if(!z.event||z.done)continue;const inside=state.hero.mesh.position.distanceTo(z.mesh.position)<z.r;z.capture=clamp(z.capture+(inside?dt:-dt*.35),0,8);if(z.capture>=8){z.done=true;z.life=.12;state.eventCount++;state.coins+=65;state.hero.hp=Math.min(state.hero.maxHp,state.hero.hp+state.hero.maxHp*.25);showToast('反应堆稳定 · +65 CR');if(state.eventCount>=2)state.questEvents=true}}}
function spawnDirector(dt){if(state.bossStarted)return;if(state.time>=600){const boss=spawnEnemy('boss',true,true);if(boss){state.bossStarted=true;$('#mainObjective').textContent='击败 OMEGA · 躲开红色预警';for(const e of state.enemies)if(!e.boss){e.dead=true;removeObject(e.mesh)}state.enemies=state.enemies.filter(e=>!e.dead);for(const p of state.enemyProjectiles)removeObject(p.mesh);state.enemyProjectiles=[];showToast('第 20 波结束 · OMEGA 决战')}}if(state.bossStarted)return;const wave=Math.min(20,Math.floor(state.time/30)+1);if(wave!==state.wave){state.wave=wave;showToast(`第 ${wave} / 20 波 · ${wave<4?'侦察群':wave<10?'混合攻势':wave<16?'重装围攻':'终末封锁'}`)}state.spawnAcc+=dt;const t=state.time,d=DIFFS[state.diff].mul,interval=Math.max(.14,.52-t/650*.34)/d;if(state.spawnAcc>interval){state.spawnAcc=0;const pool=t<90?['drone','drone','alien']:t<260?['drone','alien','gunner','brute']:['drone','alien','gunner','brute','gunner'];const n=1+(t>220?1:0)+(t>420&&Math.random()<.35?1:0);for(let i=0;i<n;i++)spawnEnemy(pick(pool),false,false,rand(9,16))}if(t-state.lastElite>58&&!state.bossStarted){state.lastElite=t;spawnEnemy(pick(['brute','gunner']),true)}const miniTimes=[150,330,480];if(state.minibossStage<miniTimes.length&&t>=miniTimes[state.minibossStage]){spawnEnemy('brute',true);state.minibossStage++;showToast(`精英阶段 ${state.minibossStage}/3 · 重装单位进入`)}if(t-state.lastChest>76){state.lastChest=t;const a=Math.random()*Math.PI*2;spawnPickup(new THREE.Vector3(Math.cos(a)*rand(8,20),0,Math.sin(a)*rand(8,20)),'chest');showToast('补给信标已投放')}if(t-state.lastEvent>88&&state.eventCount<4){state.lastEvent=t;const d=world.eventPoints[state.eventCount%world.eventPoints.length],p=new THREE.Vector3(d.x,0,d.z);createZone(p,2.5,0,55,d.color,true);state.zones[state.zones.length-1].label=d.name;showToast('地图事件 · 前往'+d.name+'稳定能源')}}
