function updateHUD(force=false){if(!state.hero)return;document.body.classList.toggle('bossFight',state.bossStarted&&!state.bossKilled);$('#waveLabel').textContent=state.bossStarted?'OMEGA / 最终决战':`WAVE ${String(state.wave||1).padStart(2,'0')} / 20`;if(state.boss){const e=state.boss;$('#bossAttack').textContent=e.warning?`${e.warning.name} · ${Math.max(0,e.warning.remaining||0).toFixed(1)}s`:`${e.hp/e.maxHp<.5?'Ⅱ / 核心狂暴':'Ⅰ / 装甲形态'} · 保持移动`;}const loc=state.hero.mesh.position,nearest=DISTRICTS.reduce((a,b)=>distSqXZ(loc,{x:a.x,z:a.z})<distSqXZ(loc,{x:b.x,z:b.z})?a:b);$('#zoneName').textContent=Math.hypot(loc.x,loc.z)<11?'中央部署平台':nearest.name;$('#kills').textContent=state.kills;$('#level').textContent=state.level;$('#coins').textContent=state.coins;$('#charge').textContent=Math.floor(state.charge);$('#heroName').textContent=CHARS[state.char].name;$('#hpText').textContent=`${Math.ceil(state.hero.hp)} / ${Math.ceil(state.hero.maxHp)}`;$('#hpBar').style.width=clamp(state.hero.hp/state.hero.maxHp*100,0,100)+'%';$('#xpText').textContent=`${Math.floor(state.xp)} / ${state.xpNeed}`;$('#xpBar').style.width=clamp(state.xp/state.xpNeed*100,0,100)+'%';const remain=Math.max(0,600-state.time),m=Math.floor(remain/60),ss=Math.floor(remain%60);$('#timer').textContent=state.bossStarted?'OMEGA':`${m}:${String(ss).padStart(2,'0')}`;const sig=JSON.stringify([state.weapons&&Object.entries(state.weapons).map(([id,w])=>[id,w.lv,w.evo]),state.passives]);if(force||state.hudSignature!==sig){state.hudSignature=sig;const d=$('#weaponDock');d.innerHTML='';for(const [id,w] of Object.entries(state.weapons)){const x=document.createElement('div');x.className='slot '+(w.evo?'evo':'');x.title=`${WEAPONS[id].name} · ${w.evo?'进化':`Lv.${w.lv}`}`;x.innerHTML=`<b>${icon(id)}</b><span>${w.evo?'EV':w.lv}</span>`;d.appendChild(x)}for(let i=Object.keys(state.weapons).length;i<5;i++){const x=document.createElement('div');x.className='slot';x.style.opacity='.28';x.innerHTML='<b>＋</b><span>空槽</span>';d.appendChild(x)}$('#passiveDock').innerHTML=Object.entries(state.passives).map(([id,lv])=>`<span title="${PASSIVES[id].name} Lv.${lv}">${icon(id)} <b>${lv}</b></span>`).join('')}$('#shieldText').textContent=state.hero.shield>0?'护盾 '+Math.ceil(state.hero.shield):'装甲完整度';updateCooldowns();updateQuests()}
let toastTimer;function showToast(s){const t=$('#toast');t.textContent=s;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2200)}
function endRun(victory=false,quit=false){if(!state.running)return;document.body.classList.remove('playing');$('#pauseBtn').classList.add('hidden');clearInput();state.running=false;state.paused=false;$('#pauseModal').classList.add('hidden');$('#levelModal').classList.add('hidden');meta.runs++;meta.totalKills+=state.kills;const reward=Math.round((state.coins+state.kills*.32+(state.questKills?50:0)+(state.questEvents?50:0)+(state.questEvo?50:0)+(victory?180:0))*DIFFS[state.diff].reward);meta.coins+=reward;if(victory)meta.clears[state.diff]=(meta.clears[state.diff]||0)+1;checkAchievements();saveMeta();const unlocked=[];if(meta.clears.normal>0)unlocked.push('高压难度');if(meta.clears.hard>0)unlocked.push('湮灭难度');$('#resultTitle').textContent=victory?'协议完成':'任务中止';$('#resultSub').textContent=quit?'主动撤离：战场数据已保存。':victory?'OMEGA 核心已摧毁，永久数据已同步。':'机体失效，回收无人机已记录本局数据。';$('#resultStats').innerHTML=`<div><b>${state.kills}</b><span class="tiny">击杀</span></div><div><b>${state.level}</b><span class="tiny">等级</span></div><div><b>${Math.floor(state.time/60)}:${String(Math.floor(state.time%60)).padStart(2,'0')}</b><span class="tiny">生存</span></div><div><b>+${reward}</b><span class="tiny">CR</span></div>`;$('#resultUnlock').textContent=unlocked.length?'解锁进度：'+unlocked.join(' · '):'';const list=$('#achievementList');const lines=[`武器进化：${state.evolutions} 次`,`精英击杀：${state.elitesKilled} 个`,`地图事件：${state.eventCount} 次`,...state.newAchievements.map(x=>'🏆 '+x)];list.innerHTML=lines.map(x=>`<div>${x}</div>`).join('');$('#resultModal').classList.remove('hidden');$('#bossWrap').classList.add('hidden')}

function frame(){requestAnimationFrame(frame);const now=performance.now(),raw=Math.min(.05,(now-lastFrame)/1000);lastFrame=now;if(state.running&&!state.paused){if(state.victoryAt&&state.time>=state.victoryAt){endRun(true);return}state.time+=raw;updateHero(raw);spawnDirector(raw);weaponTick(raw);updateSkillSequence(raw);updateDefense(raw);updateProjectiles(raw);updateEnemies(raw);if(!state.running)return;updateZones(raw);updateEventZones(raw);updateDrops(raw);if(!state.paused&&state.running)updateFX(raw);updateCompanions(raw);checkAchievements();updateHUD()}renderer.render(scene,camera)}
renderMenu();prepareHangar();frame();

