function clearInput(){for(const k of Object.keys(key))delete key[k];moveTouch.set(0,0);aimTouch.set(0,0);for(const el of document.querySelectorAll('.joy')){el.style.setProperty('--jx','0px');el.style.setProperty('--jy','0px')}}
addEventListener('blur',()=>{clearInput();if(state.running&&!state.paused)togglePause()});
document.addEventListener('visibilitychange',()=>{if(document.hidden){clearInput();if(state.running&&!state.paused)togglePause()}});
$('#pauseBtn').onclick=togglePause;
addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code)&&state.running)e.preventDefault();if(state.paused&&!$('#levelModal').classList.contains('hidden')&&$('#evolutionModal').classList.contains('hidden')&&['Digit1','Digit2','Digit3'].includes(e.code))$('#choices').children[Number(e.code.slice(-1))-1]?.click()});
