function segmentDistanceSq(a,b,p){const x=b.x-a.x,z=b.z-a.z,l=x*x+z*z,t=l?clamp(((p.x-a.x)*x+(p.z-a.z)*z)/l,0,1):0;return(p.x-a.x-x*t)**2+(p.z-a.z-z*t)**2}
function buildInventory(){return `<div>战斗技能 <b>${Object.keys(state.weapons).length}/5</b> · ${Object.entries(state.weapons).map(([id,w])=>`${WEAPONS[id].name} ${w.evo?'EV':w.lv}`).join(' / ')}</div><div>属性模块 <b>${Object.keys(state.passives).length}/6</b> · ${Object.entries(state.passives).map(([id,lv])=>`${PASSIVES[id].name} ${lv}`).join(' / ')||'尚未安装'}</div>`}
function weaponUpgradeText(id,lv){const text={pulse:'伤害提升 · Lv.3 增加弹道',blade:'切割伤害提升 · 高等级增加刃片',mine:'爆破伤害提升 · 增加布雷数量',chain:'伤害提升 · 连锁目标 +1',orbital:'轰击范围提升 · 高等级增加信标',slicer:'切割范围与伤害提升',ember:'灼烧伤害、范围与持续时间提升',sentinel:'伤害提升 · 高等级增加无人机',echo:'伤害提升 · 高等级增加刃轨',field:'辐射范围与伤害提升',vortex:'弹幕数量 +1 · 伤害提升',annihilator:'清扫范围与伤害提升'};return `Lv.${lv+1}/5 · ${text[id]}`}
let companions=[];
function updateCompanions(dt){const w=state.weapons.sentinel,n=w?Math.min(5,1+Math.floor(w.lv/2)+(state.hero.projectiles-1)+(w.evo?2:0)):0;if(companions.length!==n){for(const c of companions)removeObject(c);companions=[];for(let i=0;i<n;i++){const c=actorVisual('drone',0x95bcff,.85,.22,true).root;scene.add(c);companions.push(c)}}for(let i=0;i<n;i++){const angle=state.time*.75+i/n*Math.PI*2;companions[i].position.copy(state.hero.mesh.position).add(new THREE.Vector3(Math.cos(angle)*1.7,1.7+Math.sin(state.time*3+i)*.12,Math.sin(angle)*1.7));companions[i].rotation.y=Math.atan2(state.aim.x,state.aim.z)}}
let audioCtx=null,soundEnabled=true;const audioLast={};
function audioStart(){try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();audioCtx.resume()}catch{}}
function audioCue(type){if(!soundEnabled||!audioCtx||audioCtx.state!=='running')return;const now=audioCtx.currentTime,gap={shot:.09,hit:.09,kill:.1,level:.4}[type]||.05;if(now-(audioLast[type]??-1)<gap)return;audioLast[type]=now;const [f,end,duration,vol]=({shot:[620,180,.075,.024],hit:[220,80,.06,.017],kill:[100,28,.2,.045],level:[520,1100,.5,.045],select:[850,1300,.12,.035],dash:[220,950,.22,.04],ult:[100,650,.65,.055],xp:[1000,1500,.065,.012]})[type]||[440,880,.1,.02];const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type=type==='kill'?'sawtooth':'triangle';osc.frequency.setValueAtTime(f,now);osc.frequency.exponentialRampToValueAtTime(end,now+duration);gain.gain.setValueAtTime(vol,now);gain.gain.exponentialRampToValueAtTime(.001,now+duration);osc.connect(gain);gain.connect(audioCtx.destination);osc.start(now);osc.stop(now+duration);osc.onended=()=>{osc.disconnect();gain.disconnect()}}
$('#soundBtn').onclick=()=>{soundEnabled=!soundEnabled;$('#soundBtn').textContent='声音 '+(soundEnabled?'开':'关');if(soundEnabled)audioStart()};
$('#skillECard .skillHudName').innerHTML=icon('e')+'棱镜壁垒';$('#skillRCard .skillHudName').innerHTML=icon('r')+'离子超载';
