function bladeVisual(color){const g=new THREE.Group(),mat=new THREE.MeshBasicMaterial({color,toneMapped:false}),ring=new THREE.Mesh(new THREE.TorusGeometry(.33,.06,5,16,Math.PI*1.6),mat);g.add(ring);const edge=new THREE.Mesh(new THREE.ConeGeometry(.2,.55,3),mat.clone());edge.position.y=.35;g.add(edge);return g}
function lightningArc(a,b,color){let from=a.clone();for(let i=1;i<=5;i++){const to=a.clone().lerp(b,i/5);if(i<5)to.add(new THREE.Vector3(rand(-.3,.3),rand(-.25,.25),rand(-.3,.3)));fxLine(from,to,color,.055);from=to}}
if(document.modelContext?.registerTool){const lifecycle=new AbortController();for(const tool of [{name:'read_voidstorm_build',description:'Read current AEGIS-7 health, level and equipped skills.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({running:state.running,paused:state.paused,level:state.level,hp:state.hero?.hp||0,weapons:Object.entries(state.weapons).map(([id,w])=>({name:WEAPONS[id].name,level:w.lv,evolved:w.evo})),passives:state.passives})},{name:'choose_voidstorm_upgrade',description:'Choose one of the three currently displayed upgrade cards and resume play.',inputSchema:{type:'object',properties:{card:{type:'integer',minimum:1,maximum:3}},required:['card'],additionalProperties:false},execute:({card})=>{if(!Number.isInteger(card)||card<1||card>3||$('#levelModal').classList.contains('hidden'))throw new Error('No valid upgrade card is available');$('#choices').children[card-1].click();return{level:state.level,paused:state.paused}}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}

function steerAroundProps(pos,dir,rad,id){for(const o of obstacles){const away=pos.clone().sub(o.p).setY(0),distance=away.length(),clearance=o.rad+rad;if(distance>clearance+1.8||distance<.01)continue;away.divideScalar(distance);const toward=dir.dot(away);if(toward>0)continue;const force=(clearance+1.8-distance)/1.8;dir.addScaledVector(away,force*.85);if(toward<-.78){const tangent=new THREE.Vector3(-away.z,0,away.x);dir.addScaledVector(tangent,(id%2?1:-1)*force*.65)}}if(dir.lengthSq()>.001)dir.normalize()}

function weaponMuzzle(actor,dir){const gun=actor.mesh.getObjectByName('rig-rifle');if(gun){actor.mesh.updateMatrixWorld(true);return gun.localToWorld(new THREE.Vector3(0,.015,1.18))}return actor.mesh.position.clone().add(new THREE.Vector3(0,1.45,0)).addScaledVector(dir,.9)}
